const webhook = $('Webhook: Discover Nearby').first().json;
const body = webhook.body ?? webhook;

const geocode = $('Google: Geocode Address').first().json;

const radiusMiles = Number(body.radius_miles ?? 3);
const searchTerm = body.search_term || 'restaurant';

if (!Number.isFinite(radiusMiles) || radiusMiles <= 0) {
  throw new Error('radius_miles must be greater than 0');
}

// Prefer coordinates returned by Google Geocoding.
// Fall back to latitude/longitude supplied directly in the webhook.
let latitude;
let longitude;

if (
  geocode.status === 'OK' &&
  Array.isArray(geocode.results) &&
  geocode.results.length > 0
) {
  latitude = Number(geocode.results[0].geometry?.location?.lat);
  longitude = Number(geocode.results[0].geometry?.location?.lng);
} else {
  latitude = Number(body.latitude);
  longitude = Number(body.longitude);
}

if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
  throw new Error(
    'Could not resolve the business location. Provide a valid address or latitude/longitude.'
  );
}

const radiusKm = radiusMiles * 1.60934;

return [
  {
    json: {
      business_name: body.business_name ?? null,
      address: body.address ?? null,
      latitude,
      longitude,
      radius_miles: radiusMiles,

      apify_input: {
        searchStringsArray: [searchTerm],
        customGeolocation: {
          type: 'Point',
          coordinates: [
            longitude,
            latitude
          ],
          radiusKm
        },
        maxCrawledPlacesPerSearch: 20,
        language: 'en'
      }
    }
  }
];

const items = $input.all();

// Handle either:
// 1. Apify results already split into n8n items
// 2. One item containing an array
const places = items.flatMap(item => {
  const data = item.json;

  if (Array.isArray(data)) return data;
  if (Array.isArray(data.body)) return data.body;

  return [data];
});

// Original search coordinates from our earlier node
const request = $('Build Apify Input').first().json;

const center =
  request.apify_input?.customGeolocation?.coordinates ?? [];

const centerLng = Number(center[0]);
const centerLat = Number(center[1]);

function distanceMiles(lat1, lng1, lat2, lng2) {
  if (![lat1, lng1, lat2, lng2].every(Number.isFinite)) {
    return null;
  }

  const R = 3958.8;

  const toRad = deg => deg * Math.PI / 180;

  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) *
      Math.cos(toRad(lat2)) *
      Math.sin(dLng / 2) ** 2;

  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

const results = places
  // Don't show closed businesses
  .filter(place =>
    !place.permanentlyClosed &&
    !place.temporarilyClosed
  )
  .map(place => {
    const lat = Number(place.location?.lat);
    const lng = Number(place.location?.lng);

    const distance = distanceMiles(
      centerLat,
      centerLng,
      lat,
      lng
    );

    return {
      name: place.title ?? null,
      category: place.categoryName ?? null,

      address: place.address ?? null,
      neighborhood: place.neighborhood ?? null,

      website: place.website ?? null,
      google_maps_url: place.url ?? null,

      latitude: Number.isFinite(lat) ? lat : null,
      longitude: Number.isFinite(lng) ? lng : null,

      distance_miles:
        distance !== null
          ? Number(distance.toFixed(2))
          : null,

      rating:
        typeof place.totalScore === 'number'
          ? place.totalScore
          : null,

      reviews_count:
        typeof place.reviewsCount === 'number'
          ? place.reviewsCount
          : 0,

      price: place.price ?? null,

      image_url: place.imageUrl ?? null,

      opening_hours: Array.isArray(place.openingHours)
        ? place.openingHours
        : [],

      place_id: place.placeId ?? null,

      can_monitor: Boolean(place.website)
    };
  })
  .sort((a, b) => {
    if (a.distance_miles === null) return 1;
    if (b.distance_miles === null) return -1;

    return a.distance_miles - b.distance_miles;
  });

return [
  {
    json: {
      business_name: request.business_name,
      radius_miles: request.radius_miles,
      count: results.length,
      competitors: results
    }
  }
];
